import{_ as s,o as n,c as t,a3 as i}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-28 — Thông báo","description":"","frontmatter":{"title":"SC-28 — Thông báo"},"headers":[],"relativePath":"wireframes/user/sc-28-thong-bao.md","filePath":"wireframes/user/sc-28-thong-bao.md","lastUpdated":1791606799000}'),c={name:"wireframes/user/sc-28-thong-bao.md"};function l(d,a,e,p,o,h){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="sc-28-—-thong-bao" tabindex="-1">SC-28 — Thông báo <a class="header-anchor" href="#sc-28-—-thong-bao" aria-label="Permalink to &quot;SC-28 — Thông báo&quot;">​</a></h1><p><span class="wf-badge muted">ƯU TIÊN THẤP (MS3)</span> <span class="wf-badge info">Route: /thong-bao</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-28 · docs/02 FR-NTF-06 · docs/07 §2.16 · docs/06 endpoints 43–46</span></p><p><strong>Ai xem màn này</strong>: Thành viên đã đăng nhập (guard USER 🔒) — cả người mua lẫn chủ nhà. Mỗi người chỉ thấy thông báo của chính mình (ownership — docs/08 §9); view-all của ADMIN cho CS không thuộc màn này. <strong>Mục đích</strong>: hub tin vận hành — mọi quyết định nghiệp vụ (duyệt KYC, duyệt tin, kết quả đấu giá, hạn thanh toán, lịch xem nhà) đổ về đây kèm deep-link về <strong>đúng entity</strong>. Số trên chuông header (<code>.count</code>) và màn này là MỘT nguồn: <code>GET /notifications/unread-count</code>. <strong>Ví dụ số dùng trong bản vẽ</strong>: người xem là thành viên <code>TV-7F2A</code> (NGUYEN VAN A) — <strong>3 chưa đọc</strong>: kết quả trúng đấu giá căn <code>CT2-A18.05</code> (order <code>ord_01J9Z…</code>, hạn thanh toán 15/10/2026 14:32 GMT+7), tin <code>CT1-B09.03</code> bị từ chối kèm lý do nguyên văn, nhắc phiên <code>auc_01J9X3K8M2</code>. &quot;Bây giờ&quot; trong bản vẽ: 10/10/2026 14:35 (GMT+7).</p><h2 id="_1-desktop-—-danh-sach-unread-noi-bat-read-mo" tabindex="-1">1. Desktop — danh sách (unread nổi bật / read mờ) <a class="header-anchor" href="#_1-desktop-—-danh-sach-unread-noi-bat-read-mo" aria-label="Permalink to &quot;1. Desktop — danh sách (unread nổi bật / read mờ)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/thong-bao</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell" style="border-color:var(--wf-accent);">🔔<span class="count">3</span></span><span class="wf-avatar">TV</span></span></div><div class="wf-container"><div class="wf-row between middle"><span class="wf-title xl">Thông báo <span class="wf-badge info">3 chưa đọc</span> <span class="wf-callout">1</span></span><span class="wf-btn sm">✓ Đánh dấu tất cả đã đọc <span class="wf-callout">3</span></span></div><div class="wf-tabs" style="margin-top:10px;"><span class="wf-tab active">Tất cả (24)</span><span class="wf-tab">Chưa đọc (3)</span></div><div class="wf-col" style="gap:8px;margin-top:12px;"><div class="wf-card flat" style="border-left:3px solid var(--wf-accent);background:var(--wf-accent-soft);"><div class="pad"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-badge danger">AUCTION_RESULT</span><span class="wf-title">Bạn đã trúng đấu giá căn CT2-A18.05!</span></span><span class="wf-small">10/10/2026 14:32 (GMT+7)</span></div><div class="wf-text" style="margin-top:4px;">Giá trúng <b class="wf-money">1.950.000.000 ₫</b> · phí đấu giá 1,5% <b class="wf-money">29.250.000 ₫</b> · trừ cọc <b class="wf-money">−90.000.000 ₫</b> → còn phải trả <b class="wf-money">1.889.250.000 ₫</b> trước <b>15/10/2026 14:32</b>. Quá hạn: mất cọc + tạm ngưng quyền đấu giá. <span class="wf-callout">7</span></div><span class="wf-small wf-accent">Mở đơn thanh toán ord_01J9Z… → SC-25 <span class="wf-callout">2</span></span></div></div><div class="wf-card flat" style="border-left:3px solid var(--wf-accent);background:var(--wf-accent-soft);"><div class="pad"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-badge warn">AUCTION_REMINDER</span><span class="wf-title">Phiên đấu giá căn CT2-A18.05 sắp bắt đầu</span></span><span class="wf-small">10/10/2026 13:45</span></div><div class="wf-text" style="margin-top:4px;">Phiên `auc_01J9X3K8M2` mở lúc <b>14:00 10/10/2026 (GMT+7)</b> — bạn là 1 trong 7 thành viên ACTIVE (bí danh TV-7F2A).</div><span class="wf-small wf-accent">Vào phòng đấu giá → SC-06</span></div></div><div class="wf-card flat" style="border-left:3px solid var(--wf-accent);background:var(--wf-accent-soft);"><div class="pad"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-badge danger">LISTING_DECISION</span><span class="wf-title">Tin đăng CT1-B09.03 — NOXH HP-380 bị từ chối</span></span><span class="wf-small">09/10/2026 09:18</span></div><div class="wf-text" style="margin-top:4px;">Lý do (nguyên văn từ quản trị viên): <i>&quot;Ảnh số 3 không thuộc căn đăng bán — chụp lại mặt trong căn hộ&quot;</i>. Bạn có thể sửa và gửi duyệt lại trong &quot;Tin của tôi&quot;. <span class="wf-callout">5</span></div><span class="wf-small wf-accent">Mở tin lst_01JZK… để sửa → SC-23</span></div></div><div class="wf-card flat"><div class="pad"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-badge info">VIEWING</span><span class="wf-title wf-muted">Chủ nhà đã xác nhận lịch xem căn CT3-C12.08</span></span><span class="wf-small">08/10/2026 16:02</span></div><div class="wf-text" style="margin-top:4px;">Lịch xem: 09:00 12/10/2026 (GMT+7) — NOXH HP-380, Vĩnh Niệm, Lê Chân, Hải Phòng.</div><span class="wf-small wf-accent">Xem lịch của tôi → SC-27</span></div></div><div class="wf-card flat"><div class="pad"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-badge wf-vip">SUBSCRIPTION</span><span class="wf-title wf-muted">Gói VIP_STANDARD đã kích hoạt</span></span><span class="wf-small">08/10/2026 10:22</span></div><div class="wf-text" style="margin-top:4px;">Hạn mức 10 tin · ưu tiên hiển thị · hiệu lực đến 07/11/2026 10:22 (GMT+7).</div><span class="wf-small wf-accent">Gói của tôi → SC-26</span></div></div><div class="wf-card flat"><div class="pad"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-badge ok">KYC_DECISION</span><span class="wf-title wf-muted">Hồ sơ xác minh danh tính (CCCD) đã được duyệt</span></span><span class="wf-small">08/10/2026 10:20</span></div><div class="wf-text" style="margin-top:4px;">Bạn đã có thể: đăng tin bán · đăng ký đấu giá · đặt lịch xem nhà.</div><span class="wf-small wf-accent">Xem hồ sơ KYC → SC-21</span></div></div><div class="wf-card flat"><div class="pad"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-badge muted">SYSTEM</span><span class="wf-title wf-muted">Bảo trì hệ thống 02:00–04:00 12/10/2026</span></span><span class="wf-small">06/10/2026 18:00</span></div><div class="wf-text" style="margin-top:4px;">Trong thời gian bảo trì, đấu giá tạm ngưng nhận giá; các phiên LIVE sẽ được thông báo riêng.</div><span class="wf-small wf-muted">Không có liên kết — dòng không click được <span class="wf-callout">2</span></span></div></div></div><div class="wf-pagination"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">›</span><span class="wf-small">20/trang · mới nhất trước <span class="wf-callout">6</span></span></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-28 · docs/02 FR-NTF · docs/07 §2.16)</div><ol><li><span class="num">1</span><span><b>Unread = viền trái accent + nền tint + title đậm</b>; read = card phẳng, title muted. Badge &quot;3 chưa đọc&quot; và chuông header cùng nguồn `GET /notifications/unread-count` (endpoint 44) — đọc xong giảm NGAY (optimistic, không chờ poll). <span class="ref">FR-NTF-06</span></span></li><li><span class="num">2</span><span><b>Click dòng → điều hướng theo `deep_link`/`ref_entity`</b> (docs/07 §2.16): prefix `lst_` → SC-23 tin của tôi · `auc_` → SC-06 phiên · `ord_` → SC-25 đơn · `ky_` → SC-21 · `vwr_` → SC-27. Đồng thời gọi `PATCH /notifications/{id}/read` (45) kiểu fire-and-forget — <b>ưu tiên điều hướng, không chờ response</b>. SYSTEM không có deep_link → dòng không click. <span class="ref">docs/05 §3 SC-28</span></span></li><li><span class="num">3</span><span><b>&quot;Đánh dấu tất cả đã đọc&quot;</b> → `POST /notifications/read-all` (46): mọi dòng mất style unread + count → 0 + toast ok &quot;Đã đánh dấu tất cả thông báo là đã đọc&quot;. Không cần dialog xác nhận (không phá dữ liệu). Đang gửi → nút loading disabled. <span class="ref">FR-NTF-06</span> <span class="ref">docs/05 §1.3</span></span></li><li><span class="num">4</span><span><b>Badge loại = enum `NotificationType`</b> (docs/07 §2.16 · bảng FR-NTF docs/02 §3.9): LISTING_DECISION · KYC_DECISION · AUCTION_REMINDER · AUCTION_RESULT · ViewingStatusChanged · SYSTEM… Màu: từ chối/cảnh báo tiền = danger · duyệt/hoàn tiền = ok · nhắc = warn · kết quả/VIP = info · hệ thống = muted. FE không tự đặt loại ngoài enum. <span class="ref">docs/05 §6 StatusBadge</span></span></li><li><span class="num">5</span><span><b>Lý do từ chối hiện NGUYÊN VĂN</b> như admin gõ (10–500 ký tự) — không tóm tắt, không cắt &quot;…&quot; giữa câu; dài thì expand &quot;Xem thêm&quot;. Quy tắc này đúng cho cả KYC lẫn tin. <span class="ref">BR-KYC-04</span> <span class="ref">BR-HS-08</span></span></li><li><span class="num">6</span><span><b>Sort `created_at` desc · phân trang offset `?page=&amp;limit=20`</b> (chuẩn docs/06 §1) · giờ hiển thị `dd/MM/yyyy HH:mm` + chú GMT+7. <span class="ref">docs/05 §1.1</span></span></li><li><span class="num">7</span><span><b>Thông báo tiền luôn breakdown từng dòng</b> (giá trúng + phí + trừ cọc = còn phải trả) — không gửi số gộp; copy khớp overlay trúng giá SC-06/SC-25. <span class="ref">docs/05 §1.6</span> <span class="ref">BR-AU-14/15</span></span></li><li><span class="num">8</span><span><b>v1 không WebSocket</b>: list + unread-count refresh khi load trang, khi quay lại route, và poll 60s khi đang mở màn này (note cho FE — cùng tinh thần polling SC-06). <span class="ref">docs/05 §4</span></span></li></ol></div><h2 id="_2-mobile-360px-—-mot-cot-action-sticky" tabindex="-1">2. Mobile 360px — một cột, action sticky <a class="header-anchor" href="#_2-mobile-360px-—-mot-cot-action-sticky" aria-label="Permalink to &quot;2. Mobile 360px — một cột, action sticky&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — DANH SÁCH</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">3</span></span></div><div style="position:sticky;top:0;background:#fff;padding:8px 12px;border-bottom:1px solid var(--wf-line);"><div class="wf-row between middle"><span class="wf-title">Thông báo</span><span class="wf-btn sm">✓ Đã đọc hết</span></div><div class="wf-tabs" style="margin-top:6px;border-bottom:none;"><span class="wf-tab active">Tất cả</span><span class="wf-tab">Chưa đọc (3)</span></div></div><div class="wf-container" style="padding:10px;"><div class="wf-col" style="gap:8px;"><div class="wf-card flat" style="border-left:3px solid var(--wf-accent);background:var(--wf-accent-soft);"><div class="pad"><span class="wf-badge danger">AUCTION_RESULT</span><div class="wf-title" style="margin-top:4px;">Bạn đã trúng đấu giá căn CT2-A18.05!</div><div class="wf-text">Còn phải trả <b class="wf-money">1.889.250.000 ₫</b> trước 15/10/2026 14:32</div><span class="wf-small wf-accent">Mở đơn thanh toán →</span></div></div><div class="wf-card flat" style="border-left:3px solid var(--wf-accent);background:var(--wf-accent-soft);"><div class="pad"><span class="wf-badge warn">AUCTION_REMINDER</span><div class="wf-title" style="margin-top:4px;">Phiên CT2-A18.05 sắp bắt đầu</div><div class="wf-text">Mở lúc 14:00 hôm nay (GMT+7)</div><span class="wf-small wf-accent">Vào phòng →</span></div></div><div class="wf-card flat" style="border-left:3px solid var(--wf-accent);background:var(--wf-accent-soft);"><div class="pad"><span class="wf-badge danger">LISTING_DECISION</span><div class="wf-title" style="margin-top:4px;">Tin CT1-B09.03 bị từ chối</div><div class="wf-text">&quot;Ảnh số 3 không thuộc căn đăng bán — chụp lại mặt trong căn hộ&quot;</div><span class="wf-small wf-accent">Sửa tin →</span></div></div><div class="wf-card flat"><div class="pad"><span class="wf-badge ok">KYC_DECISION</span><div class="wf-text" style="margin-top:4px;">Hồ sơ CCCD đã được duyệt · 08/10/2026 10:20</div></div></div><div class="wf-card flat"><div class="pad"><span class="wf-badge muted">SYSTEM</span><div class="wf-text" style="margin-top:4px;">Bảo trì 02:00–04:00 12/10/2026</div></div></div></div><div class="wf-pagination"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">›</span></div></div></div></div><div class="wf-col" style="max-width:320px;justify-content:center;"><div class="wf-note"><b>Khác biệt mobile</b>: cả dòng là vùng chạm (không chỉ link) — chạm = read + điều hướng; &quot;Đã đọc hết&quot; + tabs dính dưới header để luôn với tới bằng một tay. Breakdown tiền rút gọn còn dòng cuối (&quot;còn phải trả&quot;) — bản đầy đủ nằm ở SC-25.</div><div class="wf-note">Mở từ push/email (kênh gửi kèm in-app — FR-NTF-01..05): app điều hướng thẳng `deep_link`, màn này chỉ là nơi tập hợp.</div></div></div></div><h2 id="_3-empty-—-chua-co-thong-bao-nao" tabindex="-1">3. Empty — chưa có thông báo nào <a class="header-anchor" href="#_3-empty-—-chua-co-thong-bao-nao" aria-label="Permalink to &quot;3. Empty — chưa có thông báo nào&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:560px;"><span class="wf-state-label">EMPTY STATE</span><div class="wf-card"><div class="pad"><div class="wf-empty"><span class="icon">🔕</span><div class="wf-title">Chưa có thông báo nào</div><div class="wf-text" style="margin-top:6px;">Cập nhật về duyệt KYC, kết quả duyệt tin, đấu giá, thanh toán và lịch xem nhà sẽ xuất hiện ở đây.</div><span class="wf-btn ghost" style="margin-top:12px;">Xem tin NOXH mới nhất → SC-02</span></div><span class="wf-small">Chuông header lúc này không còn `.count`. Icon 🔕 chỉ là placeholder vị trí — production dùng icon set thật (docs/05 §7: cấm emoji icon).</span></div></div></div></div><h2 id="_4-loading-error-read-all-that-bai-4-trang-thai-bat-buoc" tabindex="-1">4. Loading / Error / read-all thất bại (4 trạng thái bắt buộc) <a class="header-anchor" href="#_4-loading-error-read-all-that-bai-4-trang-thai-bat-buoc" aria-label="Permalink to &quot;4. Loading / Error / read-all thất bại (4 trạng thái bắt buộc)&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON</span><div class="wf-card"><div class="pad wf-col"><div class="wf-skeleton" style="height:64px;"></div><div class="wf-skeleton" style="height:64px;"></div><div class="wf-skeleton" style="height:64px;"></div><div class="wf-skeleton" style="height:64px;"></div><div class="wf-skeleton" style="height:64px;"></div><span class="wf-small">5 khối xám nhấp nháy mô phỏng 5 dòng; tabs + nút &quot;đã đọc hết&quot; disabled tới khi có data.</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — KHÔNG LOAD ĐƯỢC</span><div class="wf-card"><div class="pad"><div class="wf-error-box"><div class="wf-title">Không tải được thông báo</div><div class="wf-text" style="margin-top:6px;">Kiểm tra kết nối và thử lại. Nếu lỗi tiếp diễn, gọi CSKH 1900-xxx kèm mã trace bên dưới.</div><div class="wf-trace" style="margin-top:8px;">traceId: 9f3a1c7e…c21b</div><span class="wf-btn" style="margin-top:10px;">Thử lại</span></div><span class="wf-small">ErrorState + traceId rút gọn — component chuẩn docs/05 §6.</span></div></div></div><div class="wf-col"><span class="wf-state-label">READ-ALL THẤT BẠI</span><div class="wf-card"><div class="pad"><div class="wf-toast danger">Không thể đánh dấu đã đọc — thử lại. (traceId: 4b7d…02aa)</div><span class="wf-small">Giữ nguyên trạng thái unread cũ (không optimistic mù); nút enable lại sau khi toast tắt. Click 1 dòng thất bại (PATCH read lỗi) → vẫn điều hướng, count giữ nguyên, không chặn user. <span class="wf-callout danger">9</span></span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích trạng thái</div><ol><li><span class="num">9</span><span>Đủ 4 trạng thái <b>Loading → Empty → Error (+traceId) → Data</b> theo quy tắc mọi màn dữ liệu. Fail của hành động phụ (read/read-all) không bao giờ chặn hành động chính (đọc &amp; điều hướng). <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-28" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-28 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-28" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-28&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop list (unread vs read) / mobile 360 (action sticky, cả dòng chạm được) / tablet 768 (list full-width)</li><li>[ ] Đủ trạng thái: Data · Loading skeleton · Empty + CTA · Error + traceId · read-all fail toast</li><li>[ ] 7 loại notification theo enum NotificationType có badge + copy mẫu (docs/02 §3.9): LISTING_DECISION (approve/reject) · KYC_DECISION · AUCTION_REMINDER · AUCTION_RESULT (trúng/thua/không thành) · ViewingStatusChanged · SUBSCRIPTION · SYSTEM</li><li>[ ] Dòng unread vs read khác biệt rõ KHÔNG chỉ dựa màu (accessibility: thêm chấm/bold/icon)</li><li>[ ] Reason từ chối hiển thị nguyên văn, có pattern &quot;Xem thêm&quot; khi &gt; 3 dòng</li><li>[ ] Không emoji icon trong UI production (🔔/🔕/✓ trong wireframe chỉ là placeholder vị trí)</li><li>[ ] Copy giờ <code>dd/MM/yyyy HH:mm</code> + GMT+7; tiền <code>1.889.250.000 ₫</code>; lỗi theo bảng docs/06 §5</li><li>[ ] Note cho FE: poll 60s + refresh theo route; PATCH read là fire-and-forget; không WebSocket v1</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',16)])])}const f=s(c,[["render",l]]);export{g as __pageData,f as default};
